fn mirror_vertically(mesh: &WarpMesh, height: f64) -> Vec<(f64, f64)> {
    let mut out = Vec::with_capacity(mesh.points.len());
    for row in 0..mesh.rows {
        let source = mesh.rows - 1 - row;
        for col in 0..mesh.cols {
            let p = mesh.points[source * mesh.cols + col];
            out.push((p.0, height - p.1));
        }
    }
    out
}

fn close(a: (f64, f64), b: (f64, f64)) -> bool {
    (a.0 - b.0).abs() < 1e-9 && (a.1 - b.1).abs() < 1e-9
}

#[test]
fn presets_match_the_patchy_golden_control_points() {
    for &(style, bend, vertical, expected) in GOLDEN {
        let mesh = style_mesh(style, bend, vertical, W, H).expect("a preset mesh");
        assert_eq!(
            mesh.points.len() * 2,
            expected.len(),
            "{style:?} bend={bend} vertical={vertical}"
        );
        for (i, (p, e)) in mesh
            .points
            .iter()
            .zip(expected.as_chunks::<2>().0)
            .enumerate()
        {
            assert!(
                (p.0 - e[0]).abs() < 1e-9 && (p.1 - e[1]).abs() < 1e-9,
                "{style:?} bend={bend} vertical={vertical} point {i}: got {p:?}, want ({}, {})",
                e[0],
                e[1]
            );
        }
    }
}

#[test]
fn zero_bend_is_the_style_identity_grid() {
    for style in WarpStyle::ALL {
        if !style.is_preset() {
            continue;
        }
        for vertical in [false, true] {
            let mesh = style_mesh(style, 0.0, vertical, W, H).unwrap();
            let identity = identity_mesh(mesh.cols, mesh.rows, W, H);
            assert_eq!(
                mesh.points.len(),
                identity.points.len(),
                "{style:?} {vertical}"
            );
            for (i, (p, q)) in mesh.points.iter().zip(&identity.points).enumerate() {
                assert!(
                    (p.0 - q.0).abs() < 1e-9 && (p.1 - q.1).abs() < 1e-9,
                    "{style:?} vertical={vertical} point {i}: {p:?} != {q:?}"
                );
            }
        }
    }
}

#[test]
fn ungeneratable_styles_and_bad_inputs_return_none() {
    assert!(style_mesh(WarpStyle::None, 50.0, false, W, H).is_none());
    assert!(style_mesh(WarpStyle::Custom, 50.0, false, W, H).is_none());
    assert!(style_mesh(WarpStyle::Arc, f64::NAN, false, W, H).is_none());
    assert!(style_mesh(WarpStyle::Arc, 50.0, false, 0, H).is_none());
    assert!(style_mesh(WarpStyle::Arc, 50.0, false, W, -1).is_none());
}

#[test]
fn arc_sign_is_a_vertical_mirror_and_upper_mirrors_lower() {
    for bend in [25.0, 50.0, 100.0] {
        let down = style_mesh(WarpStyle::Arc, bend, false, W, H).unwrap();
        let up = style_mesh(WarpStyle::Arc, -bend, false, W, H).unwrap();
        assert_eq!(
            up.points,
            mirror_vertically(&down, H as f64),
            "negative Arc bend mirrors"
        );

        let lower = style_mesh(WarpStyle::ArcLower, bend, false, W, H).unwrap();
        let upper = style_mesh(WarpStyle::ArcUpper, bend, false, W, H).unwrap();
        assert_eq!(
            upper.points,
            mirror_vertically(&lower, H as f64),
            "Arc Upper mirrors Arc Lower"
        );

        let shell_lower = style_mesh(WarpStyle::ShellLower, bend, false, W, H).unwrap();
        let shell_upper = style_mesh(WarpStyle::ShellUpper, bend, false, W, H).unwrap();
        assert_eq!(
            shell_upper.points,
            mirror_vertically(&shell_lower, H as f64),
            "Shell Upper mirrors Shell Lower"
        );
    }
}

#[test]
fn twist_is_orientation_invariant() {
    for bend in [-100.0, -50.0, 50.0, 100.0] {
        let horizontal = style_mesh(WarpStyle::Twist, bend, false, W, H).unwrap();
        let vertical = style_mesh(WarpStyle::Twist, bend, true, W, H).unwrap();
        assert_eq!(
            horizontal.points, vertical.points,
            "Twist ignores orientation"
        );
    }
}

#[test]
fn vertical_orientation_transposes_the_grid() {
    // A non-twist preset grows from a 4x2 horizontal net to a 2x4 vertical one.
    let horizontal = style_mesh(WarpStyle::Arc, 50.0, false, W, H).unwrap();
    let vertical = style_mesh(WarpStyle::Arc, 50.0, true, W, H).unwrap();
    assert_eq!((horizontal.cols, horizontal.rows), (4, 2));
    assert_eq!((vertical.cols, vertical.rows), (2, 4));
    assert!(!close(horizontal.points[1], vertical.points[1]));
}
